import os
import math

def normalize(v):
    mag = math.sqrt(v[0]**2 + v[1]**2)
    if mag == 0: return (0,0)
    return (v[0]/mag, v[1]/mag)

def add(v1, v2, s=1.0):
    return (v1[0] + v2[0]*s, v1[1] + v2[1]*s)

def sub(v1, v2):
    return (v1[0] - v2[0], v1[1] - v2[1])

def cross_z(v1, v2):
    # 2D cross product (z-component)
    return v1[0]*v2[1] - v1[1]*v2[0]

# --- Geometry Calculation ---
# Centers
c_in = (-50.0, 25.0)
c_mid = (25.0, 0.0)
c_out = (-500.0, -75.0)

# Vectors
v_in_to_mid = sub(c_mid, c_in)
v_mid_to_out = sub(c_out, c_mid)

# Normals (perpendicular to flow, pointing to "right" of flow direction)
# If flow is (dx, dy), normal is (-dy, dx) or (dy, -dx)
# We want a consistent "outer" side. 
# For a bend turning "right" (as we go in->mid->out), the normal (dy, -dx) points outwards?
# Let's calculate cross products to check consistency or just pick one and stick to it.
# Using (dy, -dx) normal.
n1_raw = (v_in_to_mid[1], -v_in_to_mid[0])
n2_raw = (v_mid_to_out[1], -v_mid_to_out[0])

n1 = normalize(n1_raw)
n2 = normalize(n2_raw)

# Mid normal: average of n1 and n2 (bisector)
# To avoid issues with opposite normals if angle is > 180, we check dot product.
# Here angle is ~150 deg. Normals point roughly "out".
# n1 ~ (-0.31, 0.95). n2 ~ (0.99, -0.14). 
# Sum will be small. 
# Actually, for a sharp turn > 90, the "outer" normals might diverge.
# Let's just use the bisector of the *vectors* to find the flow dir at mid, then normal.
v_bis = normalize(add(normalize(v_in_to_mid), normalize(v_mid_to_out)))
n_mid_raw = (v_bis[1], -v_bis[0])
n_mid = normalize(n_mid_raw)

# Duct dimensions
width = 50.0 # Total width in XY plane (implied by Z width 50)
half_w = width / 2.0
z_pos = 25.0
z_neg = -25.0

# Generate Vertices
# Format: (x, y, z)
# We need 4 vertices per face: Top-Right, Bot-Right, Bot-Left, Top-Left (local)
# Assuming +Normal is "Right", +Z is "Top"

def get_face(center, normal):
    right = add(center, normal, half_w)
    left = add(center, normal, -half_w)
    return [
        (right[0], right[1], z_pos),  # 0: Top-Right
        (right[0], right[1], z_neg),  # 1: Bot-Right
        (left[0],  left[1],  z_neg),  # 2: Bot-Left
        (left[0],  left[1],  z_pos)   # 3: Top-Left
    ]

# Inlet Face (verts 0-3)
f_in = get_face(c_in, n1)
# Mid Face (verts 4-7)
f_mid = get_face(c_mid, n_mid)
# Outlet Face (verts 8-11)
f_out = get_face(c_out, n2)

# Combine into vertex list
vertices = f_in + f_mid + f_out

